      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória gerenciada (GC.Alloc) no método Update() devido à concatenação repetida de strings ('s += i.ToString()'), instanciação de arrays temporários ('new object[10000]') e chamadas contínuas a 'GameObject.FindObjectsOfType<GameObject>()'. Isso gera cerca de 6.7 MB de lixo por frame, disparando pausas de coleta de lixo (GC Collect) de mais de 23ms e travamentos severos.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _cachedStringBuilder;
        private MaterialPropertyBlock _propertyBlock;

        private void Awake()
        {
            _cachedStringBuilder = new StringBuilder(4096);
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i.ToString()));
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = string.Concat("Overdraw_", i.ToString());
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                // Caso seja necessário manipular strings frequentemente, reutiliza-se um StringBuilder limpo sem alocar na heap
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                // Evita chamadas custosas que varrem toda a hierarquia como FindObjectsOfType dentro de loops de frame
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    // Usa MaterialPropertyBlock para evitar instanciar e duplicar materiais na memória
                    renderer.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor("_Color", new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, strings são 'imutáveis'. Toda vez que você faz 's += algo', o jogo não altera o texto existente; ele cria uma cópia completamente nova na memória RAM e descarta a anterior. Quando isso ocorre milhares de vezes dentro de um método Update() que roda dezenas de vezes por segundo, a memória é entupida com 'lixo'. O Unity então é obrigado a pausar todo o jogo (Garbage Collector Freeze) para limpar essa sujeira, gerando travamentos perceptíveis. Para evitar isso: 1) Reutilize instâncias como StringBuilder ou buffers estáticos em vez de criar novas strings ou arrays a cada frame; 2) Nunca use FindObjectsOfType no Update(), pois ele varre toda a cena e gera novas listas na memória; 3) Use MaterialPropertyBlock se precisar mudar cores de objetos dinamicamente sem clonar o material na RAM."
    }
  ],
  "dicas_level_design": null
}

